  1→package jlsm.table.internal;
  2→
  3→import jlsm.table.PartitionConfig;
  4→import jlsm.table.PartitionDescriptor;
  5→
  6→import java.lang.foreign.MemorySegment;
  7→import java.lang.foreign.ValueLayout;
  8→import java.util.ArrayList;
  9→import java.util.List;
 10→import java.util.Objects;
 11→
 12→/**
 13→ * Routes keys to partitions via binary search on range boundaries.
 14→ *
 15→ * <p>
 16→ * Contract: Immutable routing structure built from a {@link PartitionConfig}. Provides O(log P)
 17→ * key-to-partition lookup and range-overlap queries.
 18→ *
 19→ * <p>
 20→ * Governed by: .decisions/table-partitioning/adr.md — range map with O(log P) routing. KB
 21→ * reference: .kb/distributed-systems/data-partitioning/partitioning-strategies.md#routing
 22→ */
 23→public final class RangeMap {
 24→
 25→    // Ordered list of partition descriptors (key order guaranteed by PartitionConfig validation)
 26→    private final List<PartitionDescriptor> descriptors;
 27→
 28→    /**
 29→     * Creates a range map from the given partition configuration.
 30→     *
 31→     * <p>
 32→     * Contract:
 33→     * <ul>
 34→     * <li>Receives: validated {@link PartitionConfig} with contiguous, non-overlapping ranges</li>
 35→     * <li>Returns: range map ready for routing</li>
 36→     * <li>Side effects: none</li>
 37→     * </ul>
 38→     *
 39→     * @param config the partition configuration
 40→     */
 41→    public RangeMap(PartitionConfig config) {
 42→        Objects.requireNonNull(config, "config must not be null");
 43→        this.descriptors = config.descriptors(); // already unmodifiable via PartitionConfig
 44→        assert !this.descriptors.isEmpty() : "config must have at least one partition";
 45→    }
 46→
 47→    /**
 48→     * Routes a key (as raw bytes) to the owning partition descriptor.
 49→     *
 50→     * <p>
 51→     * Contract:
 52→     * <ul>
 53→     * <li>Receives: key as {@link MemorySegment} in lexicographic byte order</li>
 54→     * <li>Returns: the {@link PartitionDescriptor} whose range contains the key</li>
 55→     * <li>Error conditions: throws {@link IllegalArgumentException} if key is outside all
 56→     * ranges</li>
 57→     * </ul>
 58→     *
 59→     * @param key the key to route
 60→     * @return the owning partition descriptor
 61→     */
 62→    public PartitionDescriptor routeKey(MemorySegment key) {
 63→        Objects.requireNonNull(key, "key must not be null");
 64→        // Binary search: find the last partition whose lowKey <= key
 65→        int lo = 0;
 66→        int hi = descriptors.size() - 1;
 67→        int candidate = -1;
 68→        while (lo <= hi) {
 69→            int mid = lo + (hi - lo) / 2;
 70→            var d = descriptors.get(mid);
 71→            int cmp = compareKeys(d.lowKey(), key);
 72→            if (cmp <= 0) {
 73→                // d.lowKey <= key — this partition is a candidate
 74→                candidate = mid;
 75→                lo = mid + 1;
 76→            } else {
 77→                hi = mid - 1;
 78→            }
 79→        }
 80→        if (candidate == -1) {
 81→            throw new IllegalArgumentException(
 82→                    "Key is below all partition ranges — no owning partition found");
 83→        }
 84→        var d = descriptors.get(candidate);
 85→        // Verify key < highKey (half-open range: [lowKey, highKey))
 86→        if (compareKeys(key, d.highKey()) >= 0) {
 87→            throw new IllegalArgumentException(
 88→                    "Key is at or above the high bound of the last candidate partition — "
 89→                            + "no owning partition found");
 90→        }
 91→        assert compareKeys(d.lowKey(), key) <= 0 : "routeKey invariant: lowKey <= key";
 92→        assert compareKeys(key, d.highKey()) < 0 : "routeKey invariant: key < highKey";
 93→        return d;
 94→    }
 95→
 96→    /**
 97→     * Returns all partition descriptors whose ranges overlap the given key range.
 98→     *
 99→     * <p>
100→     * Contract:
101→     * <ul>
102→     * <li>Receives: half-open range [fromKey, toKey)</li>
103→     * <li>Returns: list of overlapping descriptors in key order</li>
104→     * <li>Side effects: none</li>
105→     * </ul>
106→     *
107→     * @param fromKey inclusive lower bound
108→     * @param toKey exclusive upper bound
109→     * @return overlapping partition descriptors
110→     */
111→    public List<PartitionDescriptor> overlapping(MemorySegment fromKey, MemorySegment toKey) {
112→        Objects.requireNonNull(fromKey, "fromKey must not be null");
113→        Objects.requireNonNull(toKey, "toKey must not be null");
114→        // A partition [pLow, pHigh) overlaps query [from, to) iff:
115→        // pLow < to AND pHigh > from
116→        List<PartitionDescriptor> result = new ArrayList<>();
117→        for (var d : descriptors) {
118→            boolean lowBeforeTo = compareKeys(d.lowKey(), toKey) < 0;
119→            boolean highAfterFrom = compareKeys(d.highKey(), fromKey) > 0;
120→            if (lowBeforeTo && highAfterFrom) {
121→                result.add(d);
122→            }
123→        }
124→        return List.copyOf(result);
125→    }
126→
127→    /**
128→     * Returns all partition descriptors.
129→     *
130→     * @return all descriptors in key order
131→     */
132→    public List<PartitionDescriptor> all() {
133→        return descriptors;
134→    }
135→
136→    /**
137→     * Compares two {@link MemorySegment} keys using unsigned byte-lexicographic order.
138→     *
139→     * @param a first key segment
140→     * @param b second key segment
141→     * @return negative if a &lt; b, 0 if equal, positive if a &gt; b
142→     */
143→    private static int compareKeys(MemorySegment a, MemorySegment b) {
144→        assert a != null : "a must not be null";
145→        assert b != null : "b must not be null";
146→        long lenA = a.byteSize();
147→        long lenB = b.byteSize();
148→        long mismatch = a.mismatch(b);
149→        if (mismatch == -1L) {
150→            return 0;
151→        }
152→        if (mismatch == lenA) {
153→            return -1; // a is a prefix of b, so a < b
154→        }
155→        if (mismatch == lenB) {
156→            return 1; // b is a prefix of a, so a > b
157→        }
158→        int ba = Byte.toUnsignedInt(a.get(ValueLayout.JAVA_BYTE, mismatch));
159→        int bb = Byte.toUnsignedInt(b.get(ValueLayout.JAVA_BYTE, mismatch));
160→        return Integer.compare(ba, bb);
161→    }
162→}
