  1→package jlsm.table.internal;
  2→
  3→import jlsm.table.ScoredEntry;
  4→import jlsm.table.TableEntry;
  5→
  6→import java.util.ArrayList;
  7→import java.util.Comparator;
  8→import java.util.Iterator;
  9→import java.util.List;
 10→import java.util.NoSuchElementException;
 11→import java.util.Objects;
 12→import java.util.PriorityQueue;
 13→
 14→/**
 15→ * Merges results from multiple partitions into a single result set.
 16→ *
 17→ * <p>
 18→ * Contract: Stateless utility providing merge strategies for different query types. Each method
 19→ * takes per-partition results and produces a globally correct merged result.
 20→ *
 21→ * <p>
 22→ * Governed by:
 23→ * .kb/distributed-systems/data-partitioning/vector-search-partitioning.md#result-fusion
 24→ */
 25→public final class ResultMerger {
 26→
 27→    private ResultMerger() {
 28→    }
 29→
 30→    /**
 31→     * Merges top-k scored results from multiple partitions by score (descending).
 32→     *
 33→     * <p>
 34→     * Contract:
 35→     * <ul>
 36→     * <li>Receives: per-partition scored entry lists, global k limit</li>
 37→     * <li>Returns: global top-k entries sorted by score descending</li>
 38→     * <li>Side effects: none</li>
 39→     * </ul>
 40→     * Used for: vector similarity queries, full-text queries.
 41→     *
 42→     * @param partitionResults per-partition top-k results; must not be null
 43→     * @param k global result limit; must be positive
 44→     * @param <K> key type
 45→     * @return merged top-k results sorted by score descending
 46→     * @throws NullPointerException if partitionResults is null
 47→     * @throws IllegalArgumentException if k is not positive
 48→     */
 49→    public static <K> List<ScoredEntry<K>> mergeTopK(List<List<ScoredEntry<K>>> partitionResults,
 50→            int k) {
 51→        Objects.requireNonNull(partitionResults, "partitionResults must not be null");
 52→        if (k <= 0) {
 53→            throw new IllegalArgumentException("k must be positive, got: " + k);
 54→        }
 55→
 56→        // Max-heap: highest score polled first
 57→        final PriorityQueue<ScoredEntry<K>> heap = new PriorityQueue<>(
 58→                Comparator.<ScoredEntry<K>>comparingDouble(e -> e.score()).reversed());
 59→
 60→        for (final List<ScoredEntry<K>> partition : partitionResults) {
 61→            assert partition != null : "individual partition result list must not be null";
 62→            heap.addAll(partition);
 63→        }
 64→
 65→        final List<ScoredEntry<K>> result = new ArrayList<>(Math.min(k, heap.size()));
 66→        int remaining = k;
 67→        while (remaining > 0 && !heap.isEmpty()) {
 68→            result.add(heap.poll());
 69→            remaining--;
 70→        }
 71→        assert result.size() <= k : "result must contain at most k entries";
 72→        return result;
 73→    }
 74→
 75→    /**
 76→     * Merges range iteration results from multiple partitions in key order.
 77→     *
 78→     * <p>
 79→     * Contract:
 80→     * <ul>
 81→     * <li>Receives: per-partition iterators (each already in key order)</li>
 82→     * <li>Returns: single iterator producing entries in global key order</li>
 83→     * <li>Side effects: none</li>
 84→     * </ul>
 85→     * Used for: property range queries, getAllInRange.
 86→     *
 87→     * @param partitionIterators per-partition iterators in key order; must not be null
 88→     * @return merged iterator in global key order
 89→     * @throws NullPointerException if partitionIterators is null
 90→     */
 91→    public static Iterator<TableEntry<String>> mergeOrdered(
 92→            List<Iterator<TableEntry<String>>> partitionIterators) {
 93→        Objects.requireNonNull(partitionIterators, "partitionIterators must not be null");
 94→        return new MergingIterator(partitionIterators);
 95→    }
 96→
 97→    // -------------------------------------------------------------------------
 98→    // MergingIterator — N-way merge via min-heap
 99→    // -------------------------------------------------------------------------
100→
101→    /**
102→     * An iterator that performs an N-way merge of pre-sorted partition iterators using a min-heap.
103→     * Each heap entry wraps the current head element from one partition iterator.
104→     */
105→    private static final class MergingIterator implements Iterator<TableEntry<String>> {
106→
107→        /** Heap entry: the current head element from a single partition iterator. */
108→        private record HeapEntry(TableEntry<String> entry, Iterator<TableEntry<String>> source) {
109→        }
110→
111→        private static final Comparator<HeapEntry> KEY_ORDER = Comparator
112→                .comparing(e -> e.entry().key());
113→
114→        private final PriorityQueue<HeapEntry> heap;
115→
116→        MergingIterator(List<Iterator<TableEntry<String>>> partitionIterators) {
117→            assert partitionIterators != null : "partitionIterators must not be null";
118→            this.heap = new PriorityQueue<>(Math.max(1, partitionIterators.size()), KEY_ORDER);
119→            for (final Iterator<TableEntry<String>> it : partitionIterators) {
120→                assert it != null : "individual partition iterator must not be null";
121→                if (it.hasNext()) {
122→                    heap.offer(new HeapEntry(it.next(), it));
123→                }
124→            }
125→        }
126→
127→        @Override
128→        public boolean hasNext() {
129→            return !heap.isEmpty();
130→        }
131→
132→        @Override
133→        public TableEntry<String> next() {
134→            if (heap.isEmpty()) {
135→                throw new NoSuchElementException("no more entries in merged iterator");
136→            }
137→            final HeapEntry head = heap.poll();
138→            assert head != null : "polled entry must not be null";
139→            // Advance the source iterator and re-offer its next element
140→            if (head.source().hasNext()) {
141→                heap.offer(new HeapEntry(head.source().next(), head.source()));
142→            }
143→            return head.entry();
144→        }
145→    }
146→}
