  1→package jlsm.table.internal;
  2→
  3→import jlsm.table.JlsmDocument;
  4→import jlsm.table.JlsmTable;
  5→import jlsm.table.PartitionClient;
  6→import jlsm.table.PartitionDescriptor;
  7→import jlsm.table.Predicate;
  8→import jlsm.table.ScoredEntry;
  9→import jlsm.table.TableEntry;
 10→import jlsm.table.UpdateMode;
 11→
 12→import java.io.IOException;
 13→import java.util.Iterator;
 14→import java.util.List;
 15→import java.util.Objects;
 16→import java.util.Optional;
 17→
 18→/**
 19→ * In-process implementation of {@link PartitionClient} that wraps a {@link JlsmTable.StringKeyed}.
 20→ *
 21→ * <p>
 22→ * Contract: Delegates all operations directly to the wrapped table instance. No serialization or
 23→ * network overhead. This is the only implementation for the initial (in-process) deployment.
 24→ *
 25→ * <p>
 26→ * Governed by: .decisions/table-partitioning/adr.md — in-process execution, remote-capable
 27→ * interface.
 28→ */
 29→public final class InProcessPartitionClient implements PartitionClient {
 30→
 31→    private final PartitionDescriptor descriptor;
 32→    private final JlsmTable.StringKeyed table;
 33→
 34→    /**
 35→     * Creates an in-process partition client wrapping the given table.
 36→     *
 37→     * <p>
 38→     * Contract:
 39→     * <ul>
 40→     * <li>Receives: descriptor for this partition, the backing JlsmTable.StringKeyed</li>
 41→     * <li>Returns: partition client ready for operations</li>
 42→     * <li>Side effects: none</li>
 43→     * </ul>
 44→     *
 45→     * @param descriptor the partition descriptor; must not be null
 46→     * @param table the backing table for this partition; must not be null
 47→     */
 48→    public InProcessPartitionClient(PartitionDescriptor descriptor, JlsmTable.StringKeyed table) {
 49→        Objects.requireNonNull(descriptor, "descriptor must not be null");
 50→        Objects.requireNonNull(table, "table must not be null");
 51→        this.descriptor = descriptor;
 52→        this.table = table;
 53→    }
 54→
 55→    @Override
 56→    public PartitionDescriptor descriptor() {
 57→        return descriptor;
 58→    }
 59→
 60→    @Override
 61→    public void create(String key, JlsmDocument doc) throws IOException {
 62→        assert key != null : "key must not be null";
 63→        assert doc != null : "doc must not be null";
 64→        Objects.requireNonNull(key, "key must not be null");
 65→        Objects.requireNonNull(doc, "doc must not be null");
 66→        table.create(key, doc);
 67→    }
 68→
 69→    @Override
 70→    public Optional<JlsmDocument> get(String key) throws IOException {
 71→        assert key != null : "key must not be null";
 72→        Objects.requireNonNull(key, "key must not be null");
 73→        return table.get(key);
 74→    }
 75→
 76→    @Override
 77→    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
 78→        assert key != null : "key must not be null";
 79→        assert doc != null : "doc must not be null";
 80→        assert mode != null : "mode must not be null";
 81→        Objects.requireNonNull(key, "key must not be null");
 82→        Objects.requireNonNull(doc, "doc must not be null");
 83→        Objects.requireNonNull(mode, "mode must not be null");
 84→        table.update(key, doc, mode);
 85→    }
 86→
 87→    @Override
 88→    public void delete(String key) throws IOException {
 89→        assert key != null : "key must not be null";
 90→        Objects.requireNonNull(key, "key must not be null");
 91→        table.delete(key);
 92→    }
 93→
 94→    @Override
 95→    public Iterator<TableEntry<String>> getRange(String fromKey, String toKey) throws IOException {
 96→        assert fromKey != null : "fromKey must not be null";
 97→        assert toKey != null : "toKey must not be null";
 98→        Objects.requireNonNull(fromKey, "fromKey must not be null");
 99→        Objects.requireNonNull(toKey, "toKey must not be null");
100→        return table.getAllInRange(fromKey, toKey);
101→    }
102→
103→    /**
104→     * Not yet implemented — query execution through predicates requires QueryExecutor integration
105→     * which is handled by the coordinator in WU-3.
106→     *
107→     * @throws UnsupportedOperationException always
108→     */
109→    @Override
110→    public List<ScoredEntry<String>> query(Predicate predicate, int limit) throws IOException {
111→        throw new UnsupportedOperationException(
112→                "query execution is not implemented in InProcessPartitionClient; "
113→                        + "use the PartitionedTable coordinator (WU-3)");
114→    }
115→
116→    @Override
117→    public void close() throws IOException {
118→        table.close();
119→    }
120→}
