  1→package jlsm.table;
  2→
  3→import java.lang.foreign.MemorySegment;
  4→import java.util.List;
  5→import java.util.Objects;
  6→
  7→/**
  8→ * Configuration for a {@link PartitionedTable} specifying the partition layout.
  9→ *
 10→ * <p>
 11→ * Contract: Immutable configuration holding partition descriptors that must form a contiguous,
 12→ * non-overlapping coverage of the keyspace. Validated at construction time.
 13→ *
 14→ * <p>
 15→ * Governed by: .decisions/table-partitioning/adr.md — static partitions, boundaries fixed at
 16→ * creation.
 17→ */
 18→public final class PartitionConfig {
 19→
 20→    private final List<PartitionDescriptor> descriptors;
 21→
 22→    private PartitionConfig(List<PartitionDescriptor> descriptors) {
 23→        assert descriptors != null : "descriptors must not be null";
 24→        assert !descriptors.isEmpty() : "descriptors must not be empty";
 25→        this.descriptors = List.copyOf(descriptors);
 26→    }
 27→
 28→    /**
 29→     * Creates a partition configuration from a list of descriptors.
 30→     *
 31→     * <p>
 32→     * Contract:
 33→     * <ul>
 34→     * <li>Receives: list of {@link PartitionDescriptor} — must be non-empty, contiguous,
 35→     * non-overlapping, covering the full keyspace</li>
 36→     * <li>Returns: validated {@code PartitionConfig}</li>
 37→     * <li>Side effects: none</li>
 38→     * <li>Error conditions: throws {@link IllegalArgumentException} if descriptors overlap, have
 39→     * gaps, or are empty</li>
 40→     * </ul>
 41→     *
 42→     * @param descriptors the partition descriptors in key order
 43→     * @return a validated partition configuration
 44→     */
 45→    public static PartitionConfig of(List<PartitionDescriptor> descriptors) {
 46→        Objects.requireNonNull(descriptors, "descriptors must not be null");
 47→        if (descriptors.isEmpty()) {
 48→            throw new IllegalArgumentException("descriptors must contain at least one partition");
 49→        }
 50→        // Validate elements are non-null and boundaries are contiguous
 51→        for (int i = 0; i < descriptors.size(); i++) {
 52→            var d = descriptors.get(i);
 53→            Objects.requireNonNull(d,
 54→                    "descriptors must not contain null elements (index " + i + ")");
 55→            if (i > 0) {
 56→                var prev = descriptors.get(i - 1);
 57→                // prev.highKey must equal d.lowKey (contiguous, non-overlapping)
 58→                if (!segmentsEqual(prev.highKey(), d.lowKey())) {
 59→                    throw new IllegalArgumentException(
 60→                            "Partition boundary gap or overlap between partition " + (i - 1)
 61→                                    + " (highKey) and partition " + i
 62→                                    + " (lowKey): they must be equal for contiguous coverage");
 63→                }
 64→            }
 65→        }
 66→        return new PartitionConfig(descriptors);
 67→    }
 68→
 69→    /**
 70→     * Returns the unmodifiable list of partition descriptors in key order.
 71→     *
 72→     * @return partition descriptors
 73→     */
 74→    public List<PartitionDescriptor> descriptors() {
 75→        return descriptors;
 76→    }
 77→
 78→    /**
 79→     * Returns the number of partitions.
 80→     *
 81→     * @return partition count
 82→     */
 83→    public int partitionCount() {
 84→        return descriptors.size();
 85→    }
