 87→    /**
 88→     * Compares two {@link MemorySegment} keys for byte-lexicographic equality.
 89→     *
 90→     * @param a first segment
 91→     * @param b second segment
 92→     * @return true if the segments are byte-for-byte equal
 93→     */
 94→    static boolean segmentsEqual(MemorySegment a, MemorySegment b) {
 95→        assert a != null : "a must not be null";
 96→        assert b != null : "b must not be null";
